import streamlit as st
import pandas as pd
import numpy as np
import plotly.graph_objects as go
from sklearn.metrics import roc_curve, roc_auc_score, precision_recall_curve, average_precision_score

# Page Configuration
st.set_page_config(page_title="Zero-Shot CXR Evaluation", layout="wide")

# 1. Load Data Efficiently
@st.cache_data
def load_data():
    # Ensure this points to the Parquet file generated by your LanceDB script
    return pd.read_parquet("zeroshot_evaluation_results.parquet")

df = load_data()

DISEASES = [
    "Atelectasis", "Cardiomegaly", "Consolidation", "Edema", 
    "Enlarged Cardiomediastinum", "Fracture", "Lung Lesion", 
    "Lung Opacity", "Pleural Effusion", "Pleural Other", 
    "Pneumonia", "Pneumothorax", "Support Devices", "No Finding"
]
MODELS = ["MedSigLIP", "CXR_Foundation", "BioViL-T", "CheXagent"]

# 2. Sidebar Controls
st.sidebar.title("Evaluation Controls")

selected_disease = st.sidebar.selectbox("Disease Category", DISEASES)
label_set = st.sidebar.radio("Label Source", ["CheXpert", "NegBio"])
uncertainty_policy = st.sidebar.radio(
    "Uncertainty Strategy (-1 labels)", 
    ["U-Ones (-1 as Positive)", "U-Zeros (-1 as Negative)", "Drop (-1 Ignored)"]
)

# Populate view positions dynamically from the dataset
view_positions = ["All"] + sorted([v for v in df["view_position"].unique() if pd.notna(v)])
selected_view = st.sidebar.selectbox("View Position", view_positions)

selected_models = st.sidebar.multiselect("Models to Compare", MODELS, default=MODELS)

# 3. Main Dashboard Header
st.title(f"Zero-Shot Performance: {selected_disease}")
st.markdown("Compare foundation model embeddings against NLP-derived labels from MIMIC-CXR radiology reports.")

# 4. Data Filtering & Label Mapping
filtered_df = df.copy()

# Filter by View Position
if selected_view != "All":
    filtered_df = filtered_df[filtered_df["view_position"] == selected_view]

struct_key = selected_disease.replace(" ", "_")
label_col = f"label_{label_set.lower()}_{struct_key}"
raw_labels = filtered_df[label_col]

# Apply the selected Uncertainty Strategy dynamically (ROBUST BINARIZATION)
if uncertainty_policy == "U-Ones (-1 as Positive)":
    # 1.0 and -1.0 become 1, everything else (0.0, missing, NaN) becomes 0
    y_true = raw_labels.isin([1.0, 1, -1.0, -1]).astype(int)
    
elif uncertainty_policy == "U-Zeros (-1 as Negative)":
    # Only 1.0 becomes 1, everything else (-1.0, 0.0, missing) becomes 0
    y_true = raw_labels.isin([1.0, 1]).astype(int)
    
else: 
    # Drop Strategy
    # Assume missing mentions are negative (0)
    filled_labels = raw_labels.fillna(0.0)
    
    # Create a mask that excludes uncertain labels (handles both int and float)
    valid_mask = ~filled_labels.isin([-1.0, -1])
    
    filtered_df = filtered_df[valid_mask]
    
    # Binarize the remaining valid labels
    y_true = filled_labels[valid_mask].isin([1.0, 1]).astype(int)

# Ensure we have both positive and negative classes for the ROC curve
if len(y_true.unique()) < 2:
    st.error("⚠️ Not enough classes (requires both positive and negative) in the filtered dataset to compute curves. Try changing the View Position or Disease Category.")
    st.stop()

# 5. Plotting the Curves
col1, col2 = st.columns(2)

fig_roc = go.Figure()
fig_pr = go.Figure()

for model in selected_models:
    score_col = f"score_{model}_{struct_key}"
    y_scores = filtered_df[score_col]
    
    # Calculate ROC and AUC
    fpr, tpr, _ = roc_curve(y_true, y_scores)
    roc_auc = roc_auc_score(y_true, y_scores)
    fig_roc.add_trace(go.Scatter(
        x=fpr, y=tpr, mode='lines', 
        name=f'{model} (AUC = {roc_auc:.3f})'
    ))
    
    # Calculate Precision-Recall and AUC
    precision, recall, _ = precision_recall_curve(y_true, y_scores)
    pr_auc = average_precision_score(y_true, y_scores)
    fig_pr.add_trace(go.Scatter(
        x=recall, y=precision, mode='lines', 
        name=f'{model} (AUC = {pr_auc:.3f})'
    ))

# Format ROC Figure
fig_roc.add_trace(go.Scatter(x=[0, 1], y=[0, 1], mode='lines', line=dict(dash='dash', color='grey'), showlegend=False))
fig_roc.update_layout(
    title="Receiver Operating Characteristic (ROC)", 
    xaxis_title="False Positive Rate", 
    yaxis_title="True Positive Rate",
    hovermode="x unified",
    legend=dict(yanchor="bottom", y=0.01, xanchor="right", x=0.99)
)
col1.plotly_chart(fig_roc, use_container_width=True)

# Format PR Figure
baseline = sum(y_true) / len(y_true) # The prevalence of the positive class
fig_pr.add_trace(go.Scatter(x=[0, 1], y=[baseline, baseline], mode='lines', line=dict(dash='dash', color='grey'), showlegend=False))
fig_pr.update_layout(
    title="Precision-Recall (PR) Curve", 
    xaxis_title="Recall (Sensitivity)", 
    yaxis_title="Precision (PPV)",
    hovermode="x unified",
    legend=dict(yanchor="top", y=0.99, xanchor="right", x=0.99)
)
col2.plotly_chart(fig_pr, use_container_width=True)

# 6. Data Inspector
st.subheader("High/Low Confidence Inspector")
st.markdown("Review individual cases. Sort by a model's score to find images where the model was highly confident but the label disagreed.")

# Create a clean display dataframe
display_cols = ["dicom_id", "view_position", label_col] + [f"score_{m}_{struct_key}" for m in selected_models]
display_df = filtered_df[display_cols].copy()
display_df.rename(columns={label_col: "Ground Truth Label"}, inplace=True)

st.dataframe(display_df, use_container_width=True)